def test_run_command_uses_plan_parent_not_cwd():
    """The run() CLI command must pass plan_file.parent as repo_root, not Path.cwd()."""
    source = STRUCTURED_EXECUTE.read_text()
    tree = ast.parse(source)

    # Find the run() function
    run_func = None
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == "run":
            run_func = node
            break

    assert run_func is not None, "run() function not found in structured_execute.py"

    # Extract source lines of the run function
    func_source = ast.get_source_segment(source, run_func)
    assert func_source is not None, "Could not extract run() source"

    # It must NOT call Path.cwd() as an argument in executable code (comments are OK)
    executable_lines = [
        line for line in func_source.splitlines()
        if line.strip() and not line.strip().startswith("#")
    ]
    executable_code = "\n".join(executable_lines)
    assert "Path.cwd()" not in executable_code, (
        "run() still uses Path.cwd() as repo_root — should use plan_file.resolve().parent"
    )
    # Must NOT pass a hardcoded repo_root — it's now read from the plan file
    assert "execute_plan(plan_file.resolve()" in executable_code, (
        "run() should delegate to execute_plan with plan file path"
    )


