# ---------------------------------------------------------------------------
# Bug 1: subagent-service/run.sh workspace mismatch detection
# ---------------------------------------------------------------------------

def test_start_container_checks_workspace_mismatch():
    """start_container() must detect workspace mismatch on existing containers and restart."""
    if not SUBAGENT_RUN_SH.exists():
        raise FileNotFoundError(f"subagent-service/run.sh not found at {SUBAGENT_RUN_SH}")

    content = SUBAGENT_RUN_SH.read_text()

    # Must contain docker inspect for mount destination check
    assert "docker inspect" in content and "/home/node/workspace" in content, (
        "start_container() must inspect running container's mount destination to detect workspace mismatch"
    )

    # Must contain the workspace-changed restart logic (docker rm -f before falling through)
    assert "Workspace changed" in content or "workspace changed" in content.lower(), (
        "start_container() must log when workspace has changed and needs restart"
    )

    # Must NOT just return 0 unconditionally when container is already running
    # The old code had: if already running → return 0 (ignoring workspace)
    # The new code must check workspace BEFORE returning
    func_match = re.search(
        r'start_container\(\).*?^}', content, re.DOTALL | re.MULTILINE,
    )
    assert func_match, "Could not find start_container() function in run.sh"
    func_body = func_match.group()

    # Within the "already running" block, there must be a workspace check
    already_running_block = re.search(
        r'already running.*?(?=# Remove stopped|# Auto-allocate)',
        func_body, re.DOTALL,
    )
    assert already_running_block, "Could not find 'already running' block in start_container()"
    block = already_running_block.group()

    assert "workspace" in block.lower(), (
        "The 'already running' check doesn't examine workspace — will silently reuse stale mount"
    )
    assert "docker rm" in block or "docker stop" in block, (
        "When workspace mismatches, the container must be stopped/removed before recreation"
    )


def test_start_container_no_unconditional_early_return():
    """The old bug was 'return 0' without checking workspace. Verify that's fixed."""
    content = SUBAGENT_RUN_SH.read_text()

    # Extract the full already-running block (bash if with nested if/else/fi)
    # Look from the "# Check if already running" comment to the closing fi
    match = re.search(
        r'# Check if already running\n(.*?)(?=\n    # Remove stopped|    # Auto-allocate)',
        content, re.DOTALL,
    )
    assert match, "Could not find the 'already running' block"
    block = match.group()

    # Count the return 0 statements — there should be conditional returns,
    # not a single unconditional one at the top
    returns = re.findall(r'return 0', block)
    workspace_checks = re.findall(r'workspace', block, re.IGNORECASE)

    # If there are return 0s, there must also be workspace checks
    if returns:
        assert workspace_checks, (
            f"Found {len(returns)} 'return 0' in already-running block but no workspace "
            f"checks — container will be reused with stale mount"
        )


